-- Crear tabla proveedores
CREATE TABLE proveedores (
    provider_id VARCHAR(8) PRIMARY KEY,
    name VARCHAR(100),
    nif VARCHAR(15),
    email VARCHAR(100),
    phone VARCHAR(20),
    country VARCHAR(50),
    city VARCHAR(50),
    address VARCHAR(150),
    category VARCHAR(50),
    subcategory VARCHAR(50),
    condicion_pago VARCHAR(20)
);

